import json, glob
total = 0
count = 0
for path in sorted(glob.glob('data/*.jsonl')):
    for line in open(path):
        rec = json.loads(line)
        if rec.get('kind') != 'span':
            continue
        el = rec.get('body', {}).get('span', {}).get('elapsed')
        if el is None:
            continue
        v, u = el['value'], el['unit']
        if u == 'ms':
            total += v
        elif u == 'us':
            total += v // 1000
        elif u == 's':
            total += v * 1000
        else:
            raise SystemExit('unknown unit %r' % u)
        count += 1
print('spans with elapsed:', count, 'total:', total)
"
